package store

import (
	"context"
	"testing"
)

type gsrWitnessReader struct {
	calls int
}

// Read honors the contract that a call given a cancelled context returns the context's error.
func (r *gsrWitnessReader) Read(ctx context.Context, key string) (string, error) {
	r.calls++
	if err := ctx.Err(); err != nil {
		return "", err
	}
	return "", ErrRetry
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	r := &gsrWitnessReader{}
	_, err := Fetch(ctx, r, "testkey")

	if r.calls != 1 {
		t.Fatalf("Fetch(cancelledCtx) made %d calls to Read, want 1", r.calls)
	}
	if err != context.Canceled {
		t.Fatalf("Fetch(cancelledCtx) returned error %v, want context.Canceled", err)
	}
}

