package recruiter

import (
	"context"
	"errors"
	"testing"

	"github.com/weitzer-org/job_tracker/internal/storage"
)

type gsrWitnessFakeStorage struct {
	storage.Client
	writes int
	cancel context.CancelFunc
}

func (f *gsrWitnessFakeStorage) ReadFile(ctx context.Context, bucket, key string) ([]byte, string, error) {
	if err := ctx.Err(); err != nil {
		return nil, "", err
	}
	return []byte(`{}`), "etag1", nil
}

func (f *gsrWitnessFakeStorage) WriteFile(ctx context.Context, bucket, key string, data []byte, ifMatch string) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	f.writes++
	// Cancel the context simulating cancellation happening before or during the ensuing time.Sleep
	if f.cancel != nil {
		f.cancel()
	}
	return storage.ErrETagMismatch
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	fake := &gsrWitnessFakeStorage{cancel: cancel}
	s := &Store{
		Storage: fake,
		Bucket:  "test-bucket",
	}

	_, err := s.Mutate(ctx, "https://linkedin.com/in/jane", func(c Contact) Contact {
		return c
	})

	if fake.writes >= maxWriteRetries {
		t.Fatalf("Store.Mutate writes = %d, want early abort on context cancellation (< %d)", fake.writes, maxWriteRetries)
	}
	if err == nil || !errors.Is(err, context.Canceled) {
		t.Fatalf("Store.Mutate err = %v, want error wrapping context.Canceled", err)
	}
}

