	// ReadFile properly honours the now-cancelled context.
	if !errors.Is(err, context.Canceled) {
		t.Fatalf("Mutate() error = %v, want error wrapping context.Canceled (should abort early, not exhaust retries)", err)
	}
}

package recruiter

import (
	"context"
	"strings"
	"testing"

	"github.com/weitzer-org/job_tracker/internal/storage"
)

type gsrFakeStorage struct {
	storage.Client
	cancel context.CancelFunc
	writes int
}

func (f *gsrFakeStorage) ReadFile(ctx context.Context, bucket, key string) ([]byte, string, error) {
	if err := ctx.Err(); err != nil {
		return nil, "", err
	}
	return []byte(`{}`), "etag1", nil
}

func (f *gsrFakeStorage) WriteFile(ctx context.Context, bucket, key string, data []byte, ifMatch string) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	f.writes++
	// Trigger cancellation to verify the subsequent loop handles context abortion.
	if f.cancel != nil {
		f.cancel()
	}
	return storage.ErrETagMismatch
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	fake := &gsrFakeStorage{cancel: cancel}
	store := &Store{Storage: fake, Bucket: "test-bucket"}

	_, err := store.Mutate(ctx, "https://linkedin.com/in/test", func(c Contact) Contact {
		return c
	})
	if err == nil {
		t.Fatalf("Store.Mutate() = nil, want error")
	}

	if strings.Contains(err.Error(), "giving up") || fake.writes == maxWriteRetries {
		t.Fatalf("Store.Mutate() = %v, want early abort without exhausting maxWriteRetries", err)
	}
	if fake.writes != 1 {
		t.Fatalf("Store.Mutate() writes = %d, want exactly 1 before aborting", fake.writes)
	}
}
